const escapeHtml = (value) =>
  String(value)
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;')
    .replaceAll('"', '&quot;')
    .replaceAll("'", '&#39;');

/**
 * Render data as a semantic HTML table.
 *
 * @param {object} options
 * @param {string} [options.caption] - Table caption text (escaped).
 * @param {Array<{key: string, label: string, numeric?: boolean, rowHeader?: boolean}>} options.columns
 * @param {Array<Record<string, unknown>>} options.rows - Row objects keyed by column key.
 * @param {Record<string, unknown>} [options.summaryRow] - Optional tfoot summary row.
 * @returns {string} HTML markup for the table.
 */
function renderTable({ caption, columns = [], rows = [], summaryRow } = {}) {
  if (!Array.isArray(columns) || columns.length === 0) {
    throw new TypeError('renderTable requires at least one column');
  }

  const cellAttrs = (col) => {
    const attrs = [];
    if (col.numeric) attrs.push('class="num"');
    return attrs;
  };

  const renderCell = (col, value) => {
    const attrs = cellAttrs(col).join(' ');
    const open = col.rowHeader ? 'th scope="row"' : 'td';
    return `      <${open}${attrs ? ' ' + attrs : ''}>${escapeHtml(value ?? '')}</${col.rowHeader ? 'th' : 'td'}>`;
  };

  const lines = [];
  lines.push('<table>');
  if (caption != null) lines.push(`  <caption>${escapeHtml(caption)}</caption>`);
  lines.push('  <thead>');
  lines.push('    <tr>');
  for (const col of columns) {
    lines.push(`      <th scope="col">${escapeHtml(col.label)}</th>`);
  }
  lines.push('    </tr>');
  lines.push('  </thead>');

  lines.push('  <tbody>');
  for (const row of rows) {
    lines.push('    <tr>');
    for (const col of columns) {
      lines.push(renderCell(col, row?.[col.key]));
    }
    lines.push('    </tr>');
  }
  lines.push('  </tbody>');

  if (summaryRow) {
    lines.push('  <tfoot>');
    lines.push('    <tr>');
    for (const col of columns) {
      lines.push(renderCell(col, summaryRow[col.key]));
    }
    lines.push('    </tr>');
    lines.push('  </tfoot>');
  }

  lines.push('</table>');
  return lines.join('\n');
}

module.exports = { renderTable, escapeHtml };

