import { describe, it, expect } from 'vitest';
import * as cheerio from 'cheerio';
import { renderTable } from '../src/table.js';

describe('renderTable', () => {
  const columns = [
    { key: 'name', label: 'Name', rowHeader: true },
    { key: 'qty', label: 'Qty', numeric: true },
    { key: 'price', label: 'Price', numeric: true },
  ];
  const rows = [
    { name: 'Widget', qty: 3, price: '9.99' },
    { name: 'Gadget', qty: 12, price: '4.50' },
  ];

  it('renders caption text', () => {
    const $ = cheerio.load(renderTable({
      caption: 'Inventory',
      columns,
      rows,
    }));
    expect($('table > caption').text()).toBe('Inventory');
  });

  it('emits th[scope="col"] in thead and th[scope="row"] in tbody for rowHeader columns', () => {
    const $ = cheerio.load(renderTable({ caption: 'C', columns, rows }));

    const colHeaders = $('thead th');
    expect(colHeaders).toHaveLength(3);
    colHeaders.each((_, el) => {
      expect($(el).attr('scope')).toBe('col');
    });
    expect(colHeaders.eq(0).text()).toBe('Name');

    // rowHeader column: tbody cells are th with scope="row"
    const rowHeaders = $('tbody th[scope="row"]');
    expect(rowHeaders).toHaveLength(2);
    expect(rowHeaders.eq(0).text()).toBe('Widget');
    expect(rowHeaders.eq(1).text()).toBe('Gadget');
  });

  it('does not add scope=row to non-rowHeader cells and marks numeric cells with class num', () => {
    const $ = cheerio.load(renderTable({ caption: 'C', columns, rows }));
    const firstRow = $('tbody tr').first();
    expect(firstRow.find('td')).toHaveLength(2);
    const nums = firstRow.find('td.num');
    expect(nums).toHaveLength(2);
    expect(nums.first().text()).toBe('3');
    expect($('tbody td[scope]')).toHaveLength(0);
  });

  it('escapes HTML in all cell text — no script element survives parsing', () => {
    const evilRows = [{ name: '<script>alert(1)</script>', qty: 1, price: '<b>bold</b>' }];
    const html = renderTable({ caption: '<img src=x onerror=y>', columns, rows: evilRows });
    const $ = cheerio.load(html);

    expect($('script')).toHaveLength(0);
    expect($('img')).toHaveLength(0);
    expect($('tbody th[scope="row"]').first().html()).toBe(
      '&lt;script&gt;alert(1)&lt;/script&gt;'
    );
    expect($('tbody th[scope="row"]').first().text()).toBe('<script>alert(1)</script>');
    expect($('caption').text()).toBe('<img src=x onerror=y>');
    expect($('tbody td.num').last().html()).toBe('&lt;b&gt;bold&lt;/b&gt;');
  });

  it('includes tfoot only when summaryRow is provided', () => {
    const without = cheerio.load(renderTable({ caption: 'C', columns, rows }));
    expect(without('tfoot')).toHaveLength(0);

    const $ = cheerio.load(renderTable({
      caption: 'C',
      columns,
      rows,
      summaryRow: { name: 'Total', qty: 15, price: '14.49' },
    }));
    expect($('tfoot')).toHaveLength(1);
    expect($('tfoot tr')).toHaveLength(1);
    expect($('tfoot th[scope="row"]').text()).toBe('Total');
    expect($('tfoot td.num')).toHaveLength(2);
    expect($('tfoot td.num').first().text()).toBe('15');
    expect($('tfoot').next().is('table') || true).toBe(true);
  });
});

